#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-07-28

# POLICY GATE: real LLM calls must never fire automatically in CI.
#
# WHY THIS EXISTS
# Max-plan OAuth costs $0 in dollars but draws on the SHARED WEEKLY QUOTA, the
# same pool as the operator's interactive sessions. An automatically-triggered
# workflow therefore competes with the human for their own capacity, and they
# find out by being cut off mid-session.
#
# skill-eval.yml used to justify itself with the comment "Max-plan OAuth = $0
# spend". That is true about dollars and false about cost, and it is the exact
# reasoning error this gate exists to prevent from reappearing.
#
# MEASURED 2026-07-28 (PR #3181): one corpus-wide sweep touched 51 skills, 41 of
# which have eval specs. 325 prompts x 2 (with_skill + baseline) + 254 grader
# calls = ~904 API calls in a SINGLE run, re-fired on every push. That exhausted
# the weekly cap. A normal 2-skill PR is ~44 calls.
#
# THE RULE
# A workflow that invokes an LLM may only be triggered manually:
#   ALLOWED    workflow_dispatch
#   ALLOWED    pull_request: types: [labeled]   (a human clicking a label IS
#              manual approval; this is how /code-review ultra is invoked)
#   FORBIDDEN  schedule, push, issues, issue_comment, pull_request_target, and
#              any other pull_request type
#
# Evals belong in local dev: `npm run eval:skill`.

set -euo pipefail
trap 'echo "[$0] failed at line $LINENO" >&2' ERR

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
WF_DIR="$REPO_ROOT/.github/workflows"

RED=$'\033[0;31m'; GREEN=$'\033[0;32m'; YELLOW=$'\033[1;33m'; NC=$'\033[0m'

if [[ ! -d "$WF_DIR" ]]; then
    echo "${RED}FATAL: no .github/workflows directory at $WF_DIR${NC}" >&2
    echo "A gate that finds nothing to scan must not report a pass." >&2
    exit 3
fi

# Signatures of a real model invocation. Deliberately narrow: a workflow merely
# mentioning the word "claude" (e.g. claude-code-action for labels) is not an
# LLM call. These are the shapes that actually consume quota.
LLM_SIGNATURE='claude -p|eval:skill|run-quality-eval|CLAUDE_CODE_OAUTH_TOKEN|ANTHROPIC_API_KEY|anthropics/claude-code-action'

violations=0
scanned=0
llm_workflows=0

echo "▶ No automatic LLM calls in CI"
echo "────────────────────────────────────────"

for wf in "$WF_DIR"/*.yml "$WF_DIR"/*.yaml; do
    [[ -f "$wf" ]] || continue
    scanned=$((scanned + 1))
    name=$(basename "$wf")

    grep -qE "$LLM_SIGNATURE" "$wf" || continue
    llm_workflows=$((llm_workflows + 1))

    # Parse the `on:` block with python so we read YAML semantics, not regex
    # guesses. Note: YAML resolves the bare key `on` to boolean True, which is
    # why a naive text scan for "on:" gets this wrong.
    bad=$(python3 - "$wf" <<'PY'
import sys, yaml
d = yaml.safe_load(open(sys.argv[1], encoding="utf-8")) or {}
on = d.get(True, d.get("on"))
if isinstance(on, str):  on = {on: None}
if isinstance(on, list): on = {k: None for k in on}
if not isinstance(on, dict): sys.exit(0)
bad = []
for trig, cfg in on.items():
    if trig == "workflow_dispatch":
        continue
    if trig == "pull_request":
        types = (cfg or {}).get("types") if isinstance(cfg, dict) else None
        # label-gated is a manual human action; anything else is automatic
        if types == ["labeled"]:
            continue
        bad.append(f"pull_request(types={types})")
        continue
    bad.append(str(trig))
print(",".join(bad))
PY
)

    if [[ -n "$bad" ]]; then
        echo "  ${RED}✗${NC} $name invokes an LLM and fires automatically on: $bad"
        violations=$((violations + 1))
    else
        echo "  ${GREEN}✓${NC} $name (LLM, manual only)"
    fi
done

echo ""
if [[ $llm_workflows -eq 0 ]]; then
    echo "${YELLOW}⚠${NC} scanned $scanned workflows and matched no LLM signature."
    echo "Either the signatures are stale or the workflows moved. Failing rather"
    echo "than reporting a pass on a scan that measured nothing."
    exit 3
fi

if [[ $violations -gt 0 ]]; then
    echo "${RED}FAIL:${NC} $violations of $llm_workflows LLM workflow(s) can fire without approval."
    echo "Move the trigger to workflow_dispatch (or pull_request types:[labeled])."
    echo "Evals run locally: npm run eval:skill"
    exit 1
fi

echo "${GREEN}PASS:${NC} all $llm_workflows LLM workflow(s) are manual-only ($scanned scanned)."
exit 0
